INSERT INTO skill_templates (name, usage_detail, effect, tradeoff, cong_duc_cost, am_duc_cost, duration, mental_effect, mental_duration, health_effect, health_duration, spiritual_effect, spiritual_duration, ghost_level_effect, destruction_percent, category, account, oc_name, nghe, phe_duyet) VALUES ('Định Sinh', 'Kỷ Huy ném một đồng xu lên không trung, dùng linh lực cố định đồng xu tại vị trí nhất định để định trạng thái sinh mệnh của mục tiêu. Trong thời gian hiệu lực, mục tiêu được bảo hộ bởi một lớp lực vô hình. Các đòn đánh vẫn có thể tác động lên cơ thể nhưng sát thương nhận vào bị giảm đáng kể, đồng thời những thương thế vốn có sẽ không tiếp tục chuyển biến xấu. Người đang chảy máu sẽ không tiếp tục mất máu, người bị thương nặng sẽ không lập tức rơi vào trạng thái nguy hiểm hơn, đồng thời khả năng bị hất văng, gián đoạn hành động hoặc chịu một số hiệu ứng khống chế cũng được giảm bớt. Định Sinh không hồi máu. Nó chỉ giữ mục tiêu ở trạng thái an toàn trong một khoảng thời gian, tạo cơ hội để Kỷ Huy hay đồng đội tiến hành chữa trị ngay sau đó. Hắn có thể dùng Định Sinh lên bản thân. Nếu tập trung toàn bộ pháp lực vào một mục tiêu, hiệu quả bảo hộ sẽ đạt mức cao nhất.', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('Phán Âm', 'Kỷ Huy dùng đồng xu để quan sát sự vận hành của khí huyết, linh lực và âm khí trong cơ thể đối phương. Sau một khoảng thời gian quan sát, hắn có thể xác định điểm yếu hoặc nơi khí mạch mất cân bằng của mục tiêu. Kỷ Huy búng đồng xu vào vị trí đã xác định. Đồng xu không đơn thuần gây sát thương mà đánh thẳng vào điểm yếu, gây đau, làm gián đoạn vận khí và khiến mục tiêu mất khả năng phát huy một phần năng lực trong thời gian ngắn. Đối với tà vật, oán linh hoặc sinh vật mang âm khí, hiệu quả mạnh hơn. Đồng xu có thể ghim phần âm khí đang lưu chuyển, khiến mục tiêu bị trì trệ hoặc tạm thời mất một năng lực đang vận hành. Nếu hắn liên tục quan sát cùng một mục tiêu, độ chính xác của Phán Âm tăng dần. Vì vậy, đây là kỹ năng giúp hắn càng kéo dài giao chiến càng có lợi.', '', '', 0, 0, '', 'Ảo giác', 1, '', 0, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('Hoán Mệnh', 'Tung một đồng xu lên cao, dùng linh lực liên kết bản thân với đồng đội và mục tiêu đã được hắn đánh dấu. Khi đồng xu rơi xuống, hắn có thể hoán chuyển một phần trạng thái thương tổn giữa các mục tiêu. Nếu dùng lên đồng đội, Kỷ Huy có thể kéo một phần thương thế nghiêm trọng của họ về phía mình, đồng thời chuyển hóa lượng thương tổn đó thành sinh lực để hồi phục cho mục tiêu. Kỷ Huy càng nhận nhiều thương thế, hiệu quả hồi phục cho đồng đội càng lớn. Nếu dùng lên kẻ địch, hắn có thể chuyển hóa một phần thương thế mà đối phương đã gây ra cho đồng đội thành phản thương, đánh ngược lại chính kẻ gây ra nó. Đồng xu quyết định hướng vận chuyển sau khi rơi xuống: Mặt Dương: ưu tiên cứu chữa và chuyển thương về hắn. Mặt Âm: ưu tiên phản thương lên đối phương. Kỷ Huy không thể kiểm soát kết quả của đồng xu sau khi đã tung. Không thể dùng Hoán Mệnh để hồi sinh người đã chết hoặc chuyển toàn bộ thương tổn của một người sang người khác.', 'Kỷ Huy phải chịu phản phệ tương ứng với lượng thương thế được hoán chuyển. Nếu cứu một người đang ở trạng thái cực kỳ nguy hiểm, bản thân hắn có thể bị thương nặng hoặc mất khả năng tiếp tục chiến đấu trong thời gian ngắn.', '', 0, 0, '', '', 0, 'Ù tai, Khó thở, Đau đầu', 3, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('NGỌC PHIẾN ĐOẠT HỒN', 'Phiến ngọc có cơ chế giấu châm tẩm độc dược trong cán quạt. Khi không kích hoạt cơ chế bắn ra châm độc thì được sử dụng như quạt cầm tay thông thường. Sát thủ sử dụng các ám khí đã được chuẩn bị từ trước, kết hợp với độc gây suy yếu để kiểm soát khoảng cách và tạo sơ hở từ đó tập trung toàn bộ sức lực vào một đòn đánh chính xác vào điểm yếu của đổi thủ. Hiệu quả Gây tê liệt, chóng mặt, mất thị giác hoặc suy giảm khả năng vận động tùy loại độc trong bối cảnh phó bản dị sự Có thể sử dụng để ngăn đối phương truy đuổi. Có khả năng kết thúc cuộc đối đầu nếu muc tiêu đã mất khả năng phòng thủ.', '', '', 10, 0, '', 'Khỏe mạnh', 0, 'Đau đầu, Ù tai, "Hoa mắt, choáng váng"', 4, 'Thanh khiết', 0, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Tỏa Khí', 'Dùng phù lục và pháp quyết để tạm thời che giấu khí tức của bản thân và 1 người ở gần, làm giảm khả năng bị các sinh vật hoặc dị sự cảm nhận thông qua khí tức. Duy trì trong 3 cmts với Du hồn, 2 cmts với Oán hồn và 1 cmt với Lệ quỷ', 'mỗi dị sự chỉ được dùng 1 lần', '', 20, 0, '46082.0', 'Căng thẳng', 5, 'Ù tai, "Hoa mắt, choáng váng"', 4, 'Bất tịnh', 5, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Cửu Cung Định Thế', 'Dựa trên Cửu Cung và phương vị để phân chia, ghi nhớ và phân tích bố cục của một khu vực. Thông qua vị trí cửa, đường đi, vật cản và các điểm giao nhau, người sử dụng có thể xác định hướng di chuyển phù hợp hoặc vị trí thuận lợi để bố trí nhân lực và vật dụng.', '', '', 20, 0, '', 'Căng thẳng', 5, '"Hoa mắt, choáng váng", Đau đầu, Suy nhược', 5, 'Thanh khiết', 0, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Thất Tinh Liên Sát', 'Bố trí bảy trận điểm theo thế Thất Tinh, mỗi điểm đảm nhiệm một vị trí trong chuỗi công kích. Người sử dụng lần lượt kích hoạt các điểm trận để tạo thành một thế công kích liên hoàn, hạn chế khả năng hành động của mục tiêu. Khi tạo trận tối thiếu phải dùng 3 lượt cmt để bày trận, trong quá trình bày trận nếu bị ngắt quãng sẽ bị phản phệ và bày trận lại từ đầu Gây sát thương 60% lên Du hồn, 40% lên Oán hồn và 20% lên Lệ quỷ, 10% lên Hung Sát, từ Hung Sát trở lên không có tác dụng', 'Chịu phản phệ mất máu, chịu tag đỏ thể chất trong 7 cmts', '', 30, 0, '2.0', 'Nóng nảy, Căng thẳng, Không thể tập trung', 5, 'Suy nhược, Đau nhức, "Hoa mắt, choáng váng", Xuất huyết nặng', 7, 'Bất tịnh', 5, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Tiền Đồng Ngũ Đế', 'Dùng năm đồng ngũ đế theo ngũ hành để ổn định trường khí trong một phạm vi 5m, cần thiết có thể giảm ảnh hưởng của oán khí so với phạm vi, đồng thời làm suy yếu một luồng tà khí nếu thay đổi cách bày trận.', '', '', 0, 0, '2.0', 'Căng thẳng', 5, 'Đau đầu', 5, 'Thanh khiết', 0, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt'),
('Tụ Linh Trận', 'Bày một trận nhãn, sau đó bố trí 5 điểm dẫn khí xung quanh, tạo thành một vùng có năng lượng cao bình thường, tăng khả năng phục hồi năng lượng cho người ở trong trận, có thể cường hóa kỹ năng của đối phương lên thêm một bậc. Bày trận trong tối thiểu 3 cmts, nếu trong quá trình bày trận bị cắt ngang buộc phải bày lại từ đầu.', '', '', 20, 0, '2.0', 'Căng thẳng', 5, 'Đau đầu', 4, 'Thanh khiết', 0, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt'),
('Sơn Hà Chuyển Thế', 'Dùng la bàn truy tung và tiền đồng ngũ đế tạo thành một vùng trấn áp trong 5m Năm đồng ngũ đế tượng trưng cho ngũ hành, dựng ở năm điểm khác nhau có thể khóa vị trí của quỷ trong phạm vi của trận. La bàn truy tung dùng để trấn huyệt, phong tỏa cố định điểm mà nó đang đứng. Hạn chế Du hồn trong 3 cmts, oán hồn 2 cmts, lệ quỷ 1 cmts', 'Tiêu hao từ 20% đến 70% thể lực để duy trì trận pháp, tuỳ theo cấp độ quỷ dị và độ khó của dị sự. Không thể sử dụng trong 2 dị sự liên tiếp nhau', '', 46082, 0, '1 - 3', 'Mất phương hướng', 3, 'Suy nhược', 3, 'Âm khí xâm nhập', 3, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt');